+++ b/StockItemNotes.php
@@ -0,0 +1,139 @@
+<?php
+
+require(__DIR__ . '/includes/session.php');
+
+$ViewTopic = 'Inventory';// Filename in ManualContents.php's TOC.
+$BookMark = 'StockItemNotes';// Anchor's id in the manual's html document.
+$Title = __('Item Notes');
+include('includes/header.php');
+
+if (isset($_GET['StockID'])) {
+	$StockID = trim(mb_strtoupper($_GET['StockID']));
+} elseif (isset($_POST['StockID'])) {
+	$StockID = trim(mb_strtoupper($_POST['StockID']));
+}
+
+echo '<a class="toplink" href="', $RootPath, '/SelectProduct.php">', __('Back to Items'), '</a>';
+
+if (!isset($StockID) or $StockID == '') {
+	prnMsg(__('An item must be selected before its notes can be maintained. Select an item using the search page'), 'error');
+	include('includes/footer.php');
+	exit();
+}
+
+$Result = DB_query("SELECT description FROM stockmaster WHERE stockid='" . DB_escape_string($StockID) . "'");
+if (DB_num_rows($Result) == 0) {
+	prnMsg(__('Stock Item') . ' - ' . htmlspecialchars($StockID) . ' ' . __('is not defined in the database'), 'error');
+	include('includes/footer.php');
+	exit();
+}
+$DescriptionRow = DB_fetch_array($Result);
+$EscStockID = DB_escape_string($StockID);
+
+$SelectedNote = 0;
+if (isset($_GET['Edit'])) {
+	$SelectedNote = (int) $_GET['Edit'];
+} elseif (isset($_POST['NoteID'])) {
+	$SelectedNote = (int) $_POST['NoteID'];
+}
+
+if (isset($_POST['Submit'])) {
+	$Note = trim($_POST['Note']);
+	if ($Note == '') {
+		prnMsg(__('The note cannot be empty'), 'error');
+	} elseif ($SelectedNote > 0) {
+		$SQL = "UPDATE stockitemnotes
+				SET note='" . DB_escape_string($Note) . "'
+				WHERE noteid=" . $SelectedNote . "
+				AND stockid='" . $EscStockID . "'";
+		DB_query($SQL, __('The note could not be updated because'));
+		prnMsg(__('The note has been updated'), 'success');
+		$SelectedNote = 0;
+	} else {
+		$SQL = "INSERT INTO stockitemnotes (stockid, note, userid, createddate)
+				VALUES ('" . $EscStockID . "',
+					'" . DB_escape_string($Note) . "',
+					'" . DB_escape_string($_SESSION['UserID']) . "',
+					'" . date('Y-m-d H:i:s') . "')";
+		DB_query($SQL, __('The note could not be added because'));
+		prnMsg(__('The note has been added'), 'success');
+	}
+} elseif (isset($_GET['Delete'])) {
+	$SQL = "DELETE FROM stockitemnotes
+			WHERE noteid=" . (int) $_GET['Delete'] . "
+			AND stockid='" . $EscStockID . "'";
+	DB_query($SQL, __('The note could not be deleted because'));
+	prnMsg(__('The note has been deleted'), 'success');
+	$SelectedNote = 0;
+}
+
+echo '<p class="page_title_text">
+		<img src="', $RootPath, '/css/', $_SESSION['Theme'], '/images/inventory.png" title="', $Title, '" alt="" />', ' ',
+		$Title, ' ', __('For Stock Code'), ' - ', htmlspecialchars($StockID), ' - ', htmlspecialchars($DescriptionRow['description']), '
+	</p>';
+
+$Result = DB_query("SELECT noteid, note, userid, createddate
+					FROM stockitemnotes
+					WHERE stockid='" . $EscStockID . "'
+					ORDER BY noteid", __('The notes for this item could not be retrieved because'));
+
+$EditText = '';
+if (DB_num_rows($Result) == 0) {
+	prnMsg(__('There are no notes for this item'), 'info');
+} else {
+	echo '<table class="selection">
+			<thead>
+				<tr>
+					<th>', __('Date'), '</th>
+					<th>', __('User'), '</th>
+					<th>', __('Note'), '</th>
+					<th colspan="2"></th>
+				</tr>
+			</thead>
+			<tbody>';
+	while ($MyRow = DB_fetch_array($Result)) {
+		if ($MyRow['noteid'] == $SelectedNote) {
+			$EditText = $MyRow['note'];
+		}
+		$Link = htmlspecialchars(basename(__FILE__)) . '?StockID=' . urlencode($StockID) . '&amp;';
+		echo '<tr class="striped_row">
+				<td>', htmlspecialchars($MyRow['createddate']), '</td>
+				<td>', htmlspecialchars($MyRow['userid']), '</td>
+				<td>', nl2br(htmlspecialchars($MyRow['note'])), '</td>
+				<td><a href="', $Link, 'Edit=', $MyRow['noteid'], '">', __('Edit'), '</a></td>
+				<td><a href="', $Link, 'Delete=', $MyRow['noteid'], '" onclick="return confirm(\'', __('Are you sure you wish to delete this note?'), '\');">', __('Delete'), '</a></td>
+			</tr>';
+	}
+	echo '</tbody>
+		</table>';
+}
+
+// An unsaved (empty-validation failed) submission stays in the form
+if (isset($_POST['Submit']) and $SelectedNote > 0 and trim($_POST['Note']) == '') {
+	$EditText = '';
+}
+if ($EditText == '') {
+	$SelectedNote = 0;
+}
+
+echo '<form method="post" action="', htmlspecialchars(basename(__FILE__)), '">
+		<input type="hidden" name="FormID" value="', $_SESSION['FormID'], '" />
+		<input type="hidden" name="StockID" value="', htmlspecialchars($StockID), '" />
+		<input type="hidden" name="NoteID" value="', $SelectedNote, '" />
+		<fieldset>
+			<legend>', ($SelectedNote > 0 ? __('Edit Note') : __('New Note')), '</legend>
+			<field>
+				<label for="Note">', __('Note'), ':</label>
+				<textarea name="Note" id="Note" cols="60" rows="5" required="required">', htmlspecialchars($EditText), '</textarea>
+			</field>
+		</fieldset>
+		<div class="centre">
+			<input type="submit" name="Submit" value="', ($SelectedNote > 0 ? __('Update') : __('Add')), '" />
+		</div>
+	</form>';
+
+if ($SelectedNote > 0) {
+	echo '<div class="centre"><a href="', htmlspecialchars(basename(__FILE__)), '?StockID=', urlencode($StockID), '">', __('Cancel Edit'), '</a></div>';
+}
+
+include('includes/footer.php');
